import Carousel from "@marko-ui/shadcn/ui/carousel/carousel.marko";

static const ARABIC_NUMERALS = ["٠", "١", "٢", "٣", "٤", "٥", "٦", "٧", "٨", "٩"];
static function toArabicNumerals(num: number): string {
  return String(num)
    .split("")
    .map((digit) => ARABIC_NUMERALS[Number(digit)])
    .join("");
}

static const SLIDES = [1, 2, 3, 4, 5];

<Carousel|item| items=SLIDES dir="rtl" class="w-full max-w-[12rem] sm:max-w-xs">
  <div class="p-1">
    <div class="flex aspect-square items-center justify-center rounded-lg border bg-card">

      <span class="text-4xl font-semibold">${toArabicNumerals(item as number)}</span>
    </div>
  </div>
</Carousel>
